rules.suggestion:
为每个goroutine设定明确的退出机制。使用context控制生命周期，使用select+超时避免永久阻塞。

// 错误示例 - goroutine泄漏
func startWorker() {
    go func() {
        for data := range ch { // ch永远有人发送则不会退出
            process(data)
        }
    }()
}

// 正确示例 - 使用context控制生命周期
func startWorker(ctx context.Context) {
    go func() {
        for {
            select {
            case data := <-ch:
                process(data)
            case <-ctx.Done():
                return // context取消时退出
            }
        }
    }()
}

ctx, cancel := context.WithCancel(context.Background())
defer cancel()
startWorker(ctx)

将循环体提取为独立函数，在函数内使用defer。或手动调用Close()。

// 错误示例 - defer在循环中
func processFiles(files []string) error {
    for _, file := range files {
        f, err := os.Open(file)
        if err != nil {
            return err
        }
        defer f.Close() // 所有文件在processFiles返回时才关闭！
        data, _ := io.ReadAll(f)
        process(data)
    }
    return nil
}

// 正确示例 - 提取为函数
func processFiles(files []string) error {
    for _, file := range files {
        if err := processOneFile(file); err != nil {
            return err
        }
    }
    return nil
}

func processOneFile(file string) error {
    f, err := os.Open(file)
    if err != nil {
        return err
    }
    defer f.Close() // 每次调用processOneFile返回时关闭
    data, _ := io.ReadAll(f)
    return process(data)
}

始终检查error返回值。若确实不需要处理，添加注释说明原因。

// 错误示例
func readConfig(path string) map[string]string {
    data, _ := os.ReadFile(path)     // error被忽略
    var config map[string]string
    json.Unmarshal(data, &config)     // error被忽略
    return config
}

// 正确示例
func readConfig(path string) (map[string]string, error) {
    data, err := os.ReadFile(path)
    if err != nil {
        return nil, fmt.Errorf("读取配置文件失败 %s: %w", path, err)
    }
    var config map[string]string
    if err := json.Unmarshal(data, &config); err != nil {
        return nil, fmt.Errorf("解析配置文件失败: %w", err)
    }
    return config, nil
}

使用sync.Map、sync.RWMutex加锁、或使用channel串行化访问。

// 错误示例 - 并发读写map
type Cache struct {
    data map[string]interface{}
}

func (c *Cache) Set(key string, val interface{}) {
    c.data[key] = val // 并发写
}

func (c *Cache) Get(key string) interface{} {
    return c.data[key] // 并发读 -> fatal error!
}

// 正确示例 - sync.RWMutex
type SafeCache struct {
    mu   sync.RWMutex
    data map[string]interface{}
}

func (c *SafeCache) Set(key string, val interface{}) {
    c.mu.Lock()
    defer c.mu.Unlock()
    c.data[key] = val
}

func (c *SafeCache) Get(key string) interface{} {
    c.mu.RLock()
    defer c.mu.RUnlock()
    return c.data[key]
}

始终将append的返回值赋回变量。预分配slice容量避免频繁扩容。使用copy()创建独立副本。

// 错误示例 - append返回值未赋回
func addItems(s []int) {
    s = append(s, 1, 2, 3) // 局部变量s更新了，但调用者的slice未变！
}

func main() {
    items := []int{0}
    addItems(items)
    fmt.Println(items) // [0] - 数据丢失！
}

// 正确示例
func addItems(s []int) []int {
    return append(s, 1, 2, 3)
}

func main() {
    items := []int{0}
    items = addItems(items) // 接收返回值
}

明确channel的生命周期：由发送方负责关闭。使用range读取直到channel关闭。避免向已关闭或nil channel发送数据。

// 错误示例 - channel未关闭导致goroutine泄漏
func consume(ch <-chan int) {
    for {
        val := <-ch // channel无人发送且未关闭时永久阻塞
        process(val)
    }
}

// 正确示例 - 发送方关闭，接收方用range
func producer() <-chan int {
    ch := make(chan int)
    go func() {
        defer close(ch) // 发送方负责关闭
        for i := 0; i < 10; i++ {
            ch <- i
        }
    }()
    return ch
}

func consumer(ch <-chan int) {
    for val := range ch { // channel关闭后自动退出循环
        process(val)
    }
}

始终将context作为函数第一个参数传递。HTTP请求使用req.WithContext(ctx)。

// 错误示例 - 未传递context
func fetchUser(id string) (*User, error) {
    resp, err := http.Get("http://user-service/users/" + id)
    // http.Get使用Background context，无法感知请求取消
    if err != nil {
        return nil, err
    }
    defer resp.Body.Close()
    var user User
    json.NewDecoder(resp.Body).Decode(&user)
    return &user, nil
}

// 正确示例 - 传递context
func fetchUser(ctx context.Context, id string) (*User, error) {
    req, err := http.NewRequestWithContext(ctx, "GET",
        "http://user-service/users/"+id, nil)
    if err != nil {
        return nil, err
    }
    resp, err := http.DefaultClient.Do(req)
    if err != nil {
        return nil, fmt.Errorf("请求用户服务失败: %w", err)
    }
    defer resp.Body.Close()
    var user User
    if err := json.NewDecoder(resp.Body).Decode(&user); err != nil {
        return nil, err
    }
    return &user, nil
}

避免将具体类型的nil指针赋值给interface。使用显式的nil判断或返回未初始化的interface。

// 错误示例
func getUser() *User {
    user, err := findUser()
    if err != nil {
        return nil // *User的nil
    }
    return user
}

func process() {
    user := getUser()
    var i interface{} = user // type=*User, value=nil
    if i != nil { // true! 但实际是nil指针
        u := i.(*User)
        u.DoSomething() // panic: nil pointer dereference
    }
}

// 正确示例 - 在赋值前判断
var result interface{}
user := getUser()
if user != nil {
    result = user
}
// result在没有赋值时保持零值 nil interface

Go 1.22+无需额外处理。Go 1.21及以下版本：在循环体内创建局部变量副本。

// 错误示例 - Go 1.22之前
values := []string{"a", "b", "c"}
var wg sync.WaitGroup
for _, v := range values {
    wg.Add(1)
    go func() {
        defer wg.Done()
        fmt.Println(v) // 所有goroutine可能都打印"c"
    }()
}
wg.Wait()

// 正确示例 - 创建局部副本（Go 1.21及以下）
for _, v := range values {
    v := v // 创建循环内局部变量
    wg.Add(1)
    go func() {
        defer wg.Done()
        fmt.Println(v) // 正确打印各自值
    }()
}

使用json.Decoder的DisallowUnknownFields()、自定义UnmarshalJSON、或使用validator库进行校验。

// 错误示例 - 未校验
type Request struct {
    Age    int    `json:"age"`
    Name   string `json:"name"`
}

func handle(w http.ResponseWriter, r *http.Request) {
    var req Request
    json.NewDecoder(r.Body).Decode(&req) // age传"abc"变成0，不报错
    if req.Age < 18 { ... } // 0 < 18，逻辑错误
}

// 正确示例 - 使用指针检测必填字段
type Request struct {
    Age  *int    `json:"age" validate:"required,gte=0,lte=150"`
    Name *string `json:"name" validate:"required,min=1,max=50"`
}

func handle(w http.ResponseWriter, r *http.Request) {
    var req Request
    dec := json.NewDecoder(r.Body)
    dec.DisallowUnknownFields()
    if err := dec.Decode(&req); err != nil {
        http.Error(w, "invalid json", 400)
        return
    }
    if req.Age == nil || req.Name == nil {
        http.Error(w, "missing required fields", 400)
        return
    }
}

在关键入口点（HTTP handler、goroutine顶层）添加defer recover。确保recover在defer中直接调用。

// 错误示例 - recover不在defer中
func safe() {
    recover() // 无效！不是defer调用
    panic("error")
}

// 正确示例 - HTTP中间件统一恢复
func RecoveryMiddleware(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        defer func() {
            if err := recover(); err != nil {
                log.Printf("panic recovered: %v", err)
                http.Error(w, "Internal Server Error", 500)
            }
        }()
        next.ServeHTTP(w, r)
    })
}

使用unsafe包零拷贝转换（只读场景），或尽量减少转换次数，在单一类型上操作。

// 错误示例 - 循环中频繁转换
func processLines(data []byte) []string {
    var result []string
    for _, line := range bytes.Split(data, []byte("\n")) {
        s := string(line) // 每次循环分配新字符串
        result = append(result, strings.TrimSpace(s))
    }
    return result
}

// 正确示例1 - 零拷贝转换（只读场景）
func b2s(b []byte) string {
    return *(*string)(unsafe.Pointer(&b))
}

// 正确示例2 - 使用bytes包避免转换
func processLines(data []byte) [][]byte {
    lines := bytes.Split(data, []byte("\n"))
    for i, line := range lines {
        lines[i] = bytes.TrimSpace(line) // 全程使用[]byte
    }
    return lines
}

从Pool获取对象后确保独占使用，使用完毕重置状态后归还。

// 错误示例 - 未重置状态就归还
var bufPool = sync.Pool{
    New: func() interface{} { return new(bytes.Buffer) },
}

func process() {
    buf := bufPool.Get().(*bytes.Buffer)
    buf.WriteString("sensitive data")
    fmt.Println(buf.String())
    bufPool.Put(buf) // 归还时buffer中仍有数据！
}

// 正确示例
func process() {
    buf := bufPool.Get().(*bytes.Buffer)
    defer bufPool.Put(buf)
    buf.Reset() // 使用前重置
    buf.WriteString("data")
    fmt.Println(buf.String())
}

显式创建http.Server并设置合理的超时参数。

// 错误示例 - 无超时
http.ListenAndServe(":8080", mux) // 无任何超时保护

// 正确示例
server := &http.Server{
    Addr:              ":8080",
    Handler:           mux,
    ReadTimeout:       10 * time.Second,
    WriteTimeout:      30 * time.Second,
    IdleTimeout:       120 * time.Second,
    ReadHeaderTimeout: 5 * time.Second,
}

// 优雅关闭
go func() {
    if err := server.ListenAndServe(); err != http.ErrServerClosed {
        log.Fatal(err)
    }
}()

始终使用参数化查询（占位符），禁止字符串拼接SQL。动态ORDER BY等场景使用白名单校验。

// 错误示例 - SQL注入漏洞
func findUser(db *sql.DB, name string) (*User, error) {
    query := fmt.Sprintf("SELECT * FROM users WHERE name='%s'", name)
    row := db.QueryRow(query)
    // ...
}

// 正确示例 - 参数化查询
func findUser(db *sql.DB, name string) (*User, error) {
    query := "SELECT id, name, email FROM users WHERE name = $1"
    row := db.QueryRow(query, name) // 参数安全绑定
    var user User
    err := row.Scan(&user.ID, &user.Name, &user.Email)
    if err != nil {
        return nil, err
    }
    return &user, nil
}

// 动态ORDER BY使用白名单
var orderBy string
switch sortField {
case "name":
    orderBy = "name"
case "created_at":
    orderBy = "created_at"
default:
    orderBy = "id"
}
query := fmt.Sprintf("SELECT * FROM users ORDER BY %s", orderBy)
